  --color-surface:    #ffffff;
  --color-border:     #e2e6ef;
  --color-accent:     #5b5ef4;
  --color-accent-dk:  #4244d4;
  --color-text:       #1a1d2e;
  --color-muted:      #5c6080;
  --color-answer-bg:  #f3f4fb;

  --radius-lg: 14px;
  --radius-md:  8px;

  --shadow-card: 0 1px 3px rgba(0,0,0,.07), 0 4px 16px rgba(0,0,0,.06);

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 16px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

/* ─── Skip link ─────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top .15s;
}
.skip-link:focus { top: 0; }

/* ─── Header ────────────────────────────────────────────────────── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 1rem 1.5rem;
}
.header-inner {
  max-width: 780px;
  margin-inline: auto;
  display: flex;
  align-items: center;
  gap: .6rem;
}
.logo { font-size: 1.5rem; }
.site-name {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: -.02em;
  color: var(--color-accent);
}

/* ─── Main ──────────────────────────────────────────────────────── */
main { flex: 1; }

/* ─── Hero ──────────────────────────────────────────────────────── */
.hero {
  text-align: center;
  padding: 4rem 1.5rem 2.5rem;
}
.hero h1 {
  font-size: clamp(1.6rem, 4vw, 2.4rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.2;
  color: var(--color-text);
}
.hero-subtitle {
  margin-top: .75rem;
  font-size: 1.05rem;
  color: var(--color-muted);
}

/* ─── FAQ section ───────────────────────────────────────────────── */
.faq-section {
  max-width: 780px;
  margin-inline: auto;
  padding: 0 1.5rem 5rem;
}
.section-heading {
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--color-muted);
  margin-bottom: 1.25rem;
}

/* ─── FAQ list ──────────────────────────────────────────────────── */
.faq-list {
  display: flex;
  flex-direction: column;
  gap: .75rem;
}

/* ─── Example (disclosure wrapper) ─────────────────────────────── */
.example {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  transition: box-shadow .2s;
}
.example:has(button[aria-expanded="true"]) {
  box-shadow: 0 2px 8px rgba(91,94,244,.1), 0 6px 24px rgba(91,94,244,.08);
  border-color: rgba(91,94,244,.25);
}

/* ─── Question trigger ──────────────────────────────────────────── */
.example h3 {
  /* heading provides semantic structure; button is the interactive trigger */
  font-size: inherit;
  font-weight: inherit;
}

.example h3 button {
  all: unset;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 1.15rem 1.4rem;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  cursor: pointer;
  border-radius: var(--radius-lg);
  transition: background .15s;
}
.example h3 button:hover { background: #f5f5ff; }

/* Focus ring — explicit so it survives `all: unset` */
.example h3 button:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: -3px;
  border-radius: var(--radius-lg);
}

/* Chevron icon */
.example h3 button::after {
  content: '';
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  background-color: var(--color-accent);
  mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 20 20' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M5 7.5l5 5 5-5' stroke='currentColor' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  mask-size: contain;
  mask-repeat: no-repeat;
  mask-position: center;
  -webkit-mask-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 20 20' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M5 7.5l5 5 5-5' stroke='currentColor' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  -webkit-mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  -webkit-mask-position: center;
  transform: rotate(0deg);
  transition: transform .25s ease;
}
.example h3 button[aria-expanded="true"]::after {
  transform: rotate(180deg);
}

/* ─── Answer panel ──────────────────────────────────────────────── */
.details {
  background: var(--color-answer-bg);
  border-top: 1px solid var(--color-border);
  padding: 1.1rem 1.4rem 1.3rem;
  color: var(--color-muted);
  font-size: .975rem;
}
.details p { max-width: 68ch; }
.details [hidden] { display: none; }

/* ─── Footer ────────────────────────────────────────────────────── */
.site-footer {
  text-align: center;
  padding: 1.5rem 1rem;
  font-size: .85rem;
  color: var(--color-muted);
  border-top: 1px solid var(--color-border);
}

/* ─── Reduced motion ─────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .example h3 button::after { transition: none; }
  .example { transition: none; }
}

/* ─── Forced colors ─────────────────────────────────────────────── */
@media (forced-colors: active) {
  .example h3 button:focus-visible { outline: 3px solid ButtonText; }
  .example h3 button::after { background-color: ButtonText; }
}

/* ─── Reflow / narrow viewports ─────────────────────────────────── */
@media (max-width: 400px) {
  .example h3 button { padding: 1rem 1rem; font-size: .95rem; }
  .details { padding: .9rem 1rem 1.1rem; }
}
