+.site-name {
+  font-weight: 700;
+  font-size: 1.1rem;
+  letter-spacing: -.02em;
+  color: var(--color-accent);
+}
+
+/* ─── Main ──────────────────────────────────────────────────────── */
+main { flex: 1; }
+
+/* ─── Hero ──────────────────────────────────────────────────────── */
+.hero {
+  text-align: center;
+  padding: 4rem 1.5rem 2.5rem;
+}
+.hero h1 {
+  font-size: clamp(1.6rem, 4vw, 2.4rem);
+  font-weight: 800;
+  letter-spacing: -.03em;
+  line-height: 1.2;
+  color: var(--color-text);
+}
+.hero-subtitle {
+  margin-top: .75rem;
+  font-size: 1.05rem;
+  color: var(--color-muted);
+}
+
+/* ─── FAQ section ───────────────────────────────────────────────── */
+.faq-section {
+  max-width: 780px;
+  margin-inline: auto;
+  padding: 0 1.5rem 5rem;
+}
+.section-heading {
+  font-size: .75rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: .1em;
+  color: var(--color-muted);
+  margin-bottom: 1.25rem;
+}
+
+/* ─── FAQ list ──────────────────────────────────────────────────── */
+.faq-list {
+  display: flex;
+  flex-direction: column;
+  gap: .75rem;
+}
+
+/* ─── Example (disclosure wrapper) ─────────────────────────────── */
+.example {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-card);
+  overflow: hidden;
+  transition: box-shadow .2s;
+}
+.example:has(button[aria-expanded="true"]) {
+  box-shadow: 0 2px 8px rgba(91,94,244,.1), 0 6px 24px rgba(91,94,244,.08);
+  border-color: rgba(91,94,244,.25);
+}
+
+/* ─── Question trigger ──────────────────────────────────────────── */
+.example h3 {
+  /* heading provides semantic structure; button is the interactive trigger */
+  font-size: inherit;
+  font-weight: inherit;
+}
+
+.example h3 button {
+  all: unset;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
