const { chromium } = require('/tmp/node_modules/playwright');
const path = require('path');

(async () => {
  const fileUrl = 'file://' + path.resolve(process.argv[2]);
  const b = await chromium.launch();
  const page = await b.newPage();
  await page.goto(fileUrl, { waitUntil: 'networkidle' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Test 1: all panels collapsed (initial JS state)
  const r1 = await page.evaluate(async () => await window.axe.run());

  // Test 2: expand all panels
  await page.evaluate(() => {
    document.querySelectorAll('button[aria-expanded]').forEach(btn => btn.click());
  });
  const r2 = await page.evaluate(async () => await window.axe.run());

  await b.close();

  const fmt = v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target), html: v.nodes.map(n => n.html) });
  const wcag1 = r1.violations.filter(v => !v.tags.includes('best-practice'));
  const wcag2 = r2.violations.filter(v => !v.tags.includes('best-practice'));
  const bp1   = r1.violations.filter(v =>  v.tags.includes('best-practice'));
  const bp2   = r2.violations.filter(v =>  v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    collapsed: { wcag: wcag1.map(fmt), bp: bp1.map(fmt) },
    expanded:  { wcag: wcag2.map(fmt), bp: bp2.map(fmt) }
  }, null, 2));

  process.exit((wcag1.length || wcag2.length) ? 1 : 0);
})();
EOF
